import java.io.*;
import java.util.Set;

public class DeserializationExample {
    // Define a whitelist of allowed classes to prevent unauthorized deserialization
    private static final Set<String> ALLOWED_CLASSES = Set.of("java.lang.String", "java.util.ArrayList");

    public void handleRequest(InputStream inputStream) throws IOException, ClassNotFoundException {
        // Use a custom ObjectInputStream that implements look-ahead deserialization
        try (SecureObjectInputStream ois = new SecureObjectInputStream(inputStream)) {
            Object obj = ois.readObject();
            System.out.println("Received safe object: " + obj.toString());
        }
    }

    // Custom subclass to validate classes before they are instantiated
    private static class SecureObjectInputStream extends ObjectInputStream {
        public SecureObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Only allow classes defined in our whitelist
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
            }
            return super.resolveClass(desc);
        }
    }
}
